public sealed class AttemptCacheKeys(string tenant)
{
    public string Tenant { get; } = tenant;

    public string ForAttempt(string attemptId) => $"attempt:{Tenant}:{attemptId}";

    public string SessionLock => $"lock:session:{Tenant}";

    public AttemptCacheKeys(string tenant, string region) : this(tenant)
        => ArgumentException.ThrowIfNullOrWhiteSpace(region);
}

public static int TtlSeconds(string kind) => kind switch
{
    "attempt" => 300,
    "session" => 1800,
    "report" => 60,
    _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "Unknown cache kind.")
};

private string? _displayName;

public string DisplayName
{
    get => _displayName ?? "(unnamed)";
    set
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value);
        _displayName = value.Trim();
    }
}
